EXP = ['key:Escape', 'user:manager', 'click:menutop:Cash & Billing', 'click:menuleaf:Expenses']
chapter(17, 'Expenses', 'Record the plumber expense with its GST bill, let the Manager approve it, and read the recurring, petty cash, budget, Udhaar and month-lock tabs.',
        'Aarav (Reception)', 'reception', menu='Cash & Billing > Expenses')
read('You are Aarav on Modules Home. Money the hotel pays out is recorded in Expenses, never taken from the drawer without a line.', 'Every payout must have a bill and a name behind it.', target='sel:.fit-home-grid', expect='Modules Home.')
tile('Cash & Billing', 'Click the Cash & Billing tile.', 'Expenses is the last tile of the module.', expect='The Cash & Billing page opens.')
leaf('Cash & Billing', 'Expenses', 'Click the Expenses tile.', 'The page holds the register and the control tabs.', expect='The Expenses & approvals page opens.', check="ctx.page==='expenses'")
read('The tabs are Register, Recurring, Petty cash, Budgets, Udhaar and Month & tax. The register lists every expense with its status; the money figures here belong to the finance roles.', 'Reception may enter an expense but cannot approve it.', target='tab:Register', expect='The expense register and its tabs.')
click('btn:Add expense', 'Click Add expense. A plumber visited and was paid Rs 1,200 in cash.', 'The expense is entered when the money is paid, with the bill in hand.', expect='The Record an expense dialog opens.', check="has('Submit for approval')")
step('Type the vendor Sai Plumbing Works, the category Maintenance, the amount 1200 and the description: Plumber visit, room 106 geyser pipe.', 'The category decides the budget line and the ledger.', target='field:Amount', auto=['type:field:Vendor|Sai Plumbing Works', 'select:field:Category|Maintenance', 'type:field:Amount|1200', 'type:field:Description|Plumber visit, room 106 geyser pipe'], action='type', expect='The expense is described.')
click('modalbtn:Date and tax', 'Open the Date and tax section.', 'A bill with GST allows the hotel to claim input tax credit, so the GST is recorded.', expect='The GST rate, GST on bill and bill number fields appear.', check="has('GST rate')")
step('Type the GST rate 18, the GST on the bill 183 and the bill number SP-2210.', 'The accountant decides whether the input credit is allowed; the data is entered here once.', target='field:Bill / receipt number', auto=['type:field:GST rate|18', 'type:field:GST on bill|183', 'type:field:Bill / receipt number|SP-2210'], action='type', expect='GST and bill number filled.')
click('modalbtn:Photo and notes', 'Open the Photo and notes section.', 'A photo of the paper bill is attached here with the phone or the PC camera; the demo does not attach one.', expect='The bill photo and the notes appear.')
click('modalbtn:Submit for approval', 'Click Submit for approval.', 'Small expenses can wait for the manager; the money leaves the drawer only after approval.', expect='The expense waits for approval.', msgText='Expense submitted for approval')
step('Meera, the Manager, opens Expenses and finds the request in Approval requests. She clicks Approve & post for the plumber.', 'A different person always approves, so nobody pays out and approves the same bill.', target='btnin:Sai Plumbing|Approve & post',
     auto=['key:Escape', 'user:manager', 'click:menutop:Cash & Billing', 'click:menuleaf:Expenses', 'click:btn:Approval requests'], action='click', expect='The request shows Approve & post, Reject and Edit.', check="has('Approve & post')")
click('btnin:Sai Plumbing|Approve & post', 'Click Approve & post.', 'The expense is posted: the cash leaves the drawer, the GST goes to the input-credit ledger and the bill appears in Accounting.', expect='The expense is approved and posted.')
step('Sagar, the Owner, opens the Recurring tab.', 'A recurring template creates the same expense every month, for example the electricity bill; only the Owner makes templates.', target='tab:Recurring',
     auto=['key:Escape', 'user:owner', 'click:menutop:Cash & Billing', 'click:menuleaf:Expenses', 'click:tab:Recurring'], action='click', expect='The recurring templates are listed.')
click('tab:Petty cash', 'Open the Petty cash tab.', 'A petty cash float is a small sum kept for small payouts; its balance is counted like the drawer.', expect='The petty cash float and its movements are shown.')
click('tab:Budgets', 'Open the Budgets tab.', 'The Owner sets a monthly budget per category and sees where it is overspent.', expect='The budgets are shown.')
click('tab:Udhaar', 'Open the Udhaar tab.', 'Udhaar is credit given to a customer or staff; it stays a receivable until repaid.', expect='The Udhaar list opens.')
click('tab:Month', 'Open the Month & tax tab.', 'The Owner locks a month once the accounts are final and can unlock it with a reason; locked months accept no new expenses.', expect='The month lock and the tax summary open.')
